CREATE TABLE `sys_device` (
  `id` int NOT NULL AUTO_INCREMENT,
  `addr` varchar(50) NOT NULL,
  `name` varchar(50) NOT NULL,
  `product` int DEFAULT NULL,
  `dk` varchar(8) DEFAULT NULL,
