  `owner` int NOT NULL DEFAULT '1',
  `owner_dept` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `devId` (`addr`)
) ENGINE=InnoDB AUTO_INCREMENT=1607 DEFAULT CHARSET=utf8mb3 COMMENT='设备表';
